def main():
    print(f"HAAD/DHA Topics Count: {len(HAAD_DHA_TOPICS)}")
    print(f"UHS Topics Count: {len(UHS_TOPICS)}")
    print(f"PLAB Topics Count: {len(PLAB_TOPICS)}")

    assert len(HAAD_DHA_TOPICS) == 100
    assert len(UHS_TOPICS) == 100
    assert len(PLAB_TOPICS) == 100

    for name, lst in [("HAAD/DHA", HAAD_DHA_TOPICS), ("UHS", UHS_TOPICS), ("PLAB", PLAB_TOPICS)]:
        for i, t in enumerate(lst):
            assert t[1] in TAXONOMY_SUBJECTS, f"Invalid subject {t[1]} at {name} #{i}: {t[0]}"
            assert t[2] in TAXONOMY_SYSTEMS, f"Invalid system {t[2]} at {name} #{i}: {t[0]}"
            assert t[5].startswith("https://"), f"Invalid URL at {name} #{i}: {t[5]}"

    out_path = os.path.join(os.path.dirname(__file__), "mega118_topics.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 118 topics (HAAD/DHA 100, UHS 100, PLAB 100)\n\n")
        f.write(f"HAAD_DHA_TOPICS = {json.dumps(HAAD_DHA_TOPICS, indent=2)}\n\n")
        f.write(f"UHS_TOPICS = {json.dumps(UHS_TOPICS, indent=2)}\n\n")
        f.write(f"PLAB_TOPICS = {json.dumps(PLAB_TOPICS, indent=2)}\n")

    print(f"Saved Mega-Batch 118 topics to {out_path}!")

if __name__ == "__main__":
    main()
